// ═══ StampedLock — three modes ═══
StampedLock sl = new StampedLock();

// MODE 1: Write lock (exclusive)
long writeStamp = sl.writeLock();
try {
    balance = balance.subtract(amount);
} finally {
    sl.unlockWrite(writeStamp);
}

// MODE 2: Read lock (shared — blocks writers)
long readStamp = sl.readLock();
try {
    return balance;
} finally {
    sl.unlockRead(readStamp);
}

// MODE 3: Optimistic read (NO LOCK! Just validate!)
long stamp = sl.tryOptimisticRead();  // get stamp — NO lock acquired!
BigDecimal localBalance = balance;     // read shared data
BigDecimal localRate = interestRate;   // read more shared data
if (sl.validate(stamp)) {             // was there a write since stamp?
    return localBalance;               // NO write → data is VALID! Zero lock overhead!
} else {
    // Write happened! Fall back to read lock:
    long readStamp2 = sl.readLock();
    try { return balance; }
    finally { sl.unlockRead(readStamp2); }
}

// ═══ WHY OPTIMISTIC BEATS ReadWriteLock ═══
// ReadWriteLock readLock():
//   Must CAS the reader count → shared state modification!
//   Even readers contend on the CAS → cache line ping-pong!
//   Under 100 reader threads: significant contention!
//
// StampedLock tryOptimisticRead():
//   Just reads the stamp (volatile read) → NO CAS! NO state change!
//   validate() → just compares stamp → NO CAS!
//   100 readers: ZERO contention!
//   Only falls back to readLock if a write occurred (rare in read-heavy!)

// ═══ LIMITATIONS ═══
// 1. NOT reentrant! Can't lock twice from same thread (deadlock!)
// 2. NOT condition-aware! No newCondition() like ReentrantLock
// 3. Optimistic read must be SHORT — longer read = more chance of invalidation
// 4. Must copy data to LOCAL variables before validate!
//    (can't validate then read — data might change between!)
