// ─── File: src/test/java/com/bank/stamped/StampedLockTest.java ───
package com.bank.stamped;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class StampedLockTest {

    // ═══ Optimistic read: no write → valid ═══
    @Test
    void optimisticRead_noWrite_valid() {
        StampedLock sl = new StampedLock();
        int[] balance = {100000};

        long stamp = sl.tryOptimisticRead();
        int localBalance = balance[0];  // read
        assertThat(sl.validate(stamp)).isTrue();  // no write → valid!
        assertThat(localBalance).isEqualTo(100000);
    }

    // ═══ Optimistic read: write happened → invalid → fallback ═══
    @Test
    void optimisticRead_writeHappened_fallback() {
        StampedLock sl = new StampedLock();
        int[] balance = {100000};

        long stamp = sl.tryOptimisticRead();
        // Simulate write between read and validate:
        long ws = sl.writeLock();
        balance[0] = 50000;
        sl.unlockWrite(ws);

        assertThat(sl.validate(stamp)).isFalse();  // write happened → INVALID!

        // Fallback to read lock:
        long rs = sl.readLock();
        try {
            assertThat(balance[0]).isEqualTo(50000);  // correct updated value!
        } finally { sl.unlockRead(rs); }
    }

    // ═══ Concurrent: many optimistic readers + occasional writer ═══
    @Test
    void concurrent_optimisticReaders_withWriter() throws InterruptedException {
        StampedLock sl = new StampedLock();
        int[] balance = {100000};
        AtomicInteger successfulOptimistic = new AtomicInteger(0);
        AtomicInteger fallbackToReadLock = new AtomicInteger(0);
        int readers = 50;
        CountDownLatch done = new CountDownLatch(readers + 1);

        // 50 optimistic readers:
        for (int i = 0; i < readers; i++) {
            new Thread(() -> {
                for (int j = 0; j < 1000; j++) {
                    long stamp = sl.tryOptimisticRead();
                    int local = balance[0];
                    if (sl.validate(stamp)) {
                        successfulOptimistic.incrementAndGet();
                    } else {
                        long rs = sl.readLock();
                        try { local = balance[0]; }
                        finally { sl.unlockRead(rs); }
                        fallbackToReadLock.incrementAndGet();
                    }
                }
                done.countDown();
            }).start();
        }

        // 1 writer:
        new Thread(() -> {
            for (int j = 0; j < 100; j++) {
                long ws = sl.writeLock();
                try { balance[0] -= 1000; }
                finally { sl.unlockWrite(ws); }
                try { Thread.sleep(1); } catch (InterruptedException e) { }
            }
            done.countDown();
        }).start();

        done.await(30, TimeUnit.SECONDS);
        System.out.println("Optimistic success: " + successfulOptimistic.get());
        System.out.println("Fallback to readLock: " + fallbackToReadLock.get());
        // Vast majority: optimistic success! Very few fallbacks!
        assertThat(successfulOptimistic.get()).isGreaterThan(fallbackToReadLock.get() * 10);
    }

    // ═══ StampedLock is NOT reentrant! ═══
    @Test
    void notReentrant_wouldDeadlock() {
        StampedLock sl = new StampedLock();
        long stamp1 = sl.readLock();
        // long stamp2 = sl.writeLock();  // DEADLOCK! Not reentrant!
        sl.unlockRead(stamp1);
    }
}
